import streamlit as st
import pandas as pd
import requests
from datetime import datetime, timedelta
import random
import math

st.set_page_config(page_title="Tipster Pro - Calibração de Médias & Botão Automático", layout="wide")

# ==========================================
# 🔑 CHAVE DA API INTEGRADA
API_KEY = "4cd900e44cb240f7b7ef7f2c2b95b423"
