                    tipos_por_jogo = {jg: set() for jg in jogos_escolhidos}
                    probs_lista = []
                    
                    for jg in jogos_escolhidos:
                        partida_nome = jg.split(" | ")[1]
                        mandante = partida_nome.split(" x ")[0]
                        visitante = partida_nome.split(" x ")[1]
                        
