        {"Fixture ID": 1001, "Liga Categoria": "Brasileirão Série A", "Data": data_base.strftime("%Y-%m-%d"), "Horário": "19:00", "Mandante": "Sao Paulo", "Visitante": "Atletico-MG", "Árbitro API": "Wilton Sampaio"},
