            {"num": "14", "nome": "Giorgian de Arrascaeta", "pos": "Meia", "media_gols": 0.40, "media_finalizacoes_5j": 3.0, "media_chutes_5j": 1.2, "media_f_sof_5j": 2.8, "media_f_com_5j": 1.2, "media_cartoes_5j": 0.2},
