                            st.markdown(f"⚠️ **Faltas Cometidas (Últ. 5J):** `{p['media_f_com_5j']}`")
                            
                            sugestoes = []
                            if p['media_gols'] >= 0.3: sugestoes.append("0.5+ Gols")
