                catalogo = []
                for cat_m in mercados_todos:
                    catalogo.extend(obter_opcoes_por_categoria(m, v, cat_m, API_KEY))
                
                if not catalogo:
                    st.warning("Elencos ainda não disponíveis para esta partida.")
                else:
                    bilhetes_gerados = []
