# --- 0. MOTOR MATEMÁTICO EXATO SUPERBET (CRIAR APOSTA) ---
def calcular_odd_bilhete(odds_list, tipo_bilhete="Criar Aposta"):
    if not odds_list: return 1.00
    if tipo_bilhete == "Aposta Simples":
        return round(odds_list[0], 2)
    else:
        produto = math.prod(odds_list)
        if len(odds_list) == 1:
            return round(produto, 2)
            
        # Penalidade de Correlação Superbet para múltiplos mercados no mesmo jogo
        # A odd final em um Bet Builder é sempre ligeiramente menor que o produto real
        fator_correlacao = 0.94 - (0.025 * len(odds_list))
        fator_correlacao = max(0.80, fator_correlacao) # Limite máximo de corte da casa
        
        odd_final = produto ** fator_correlacao
        return round(max(1.10, odd_final), 2)

