                odds_selecoes, probs_lista, tipos_usados, detalhes_por_jogo = [], [], set(), {jg: [] for jg in jogos_escolhidos}
                
                # Distribui mercados variados entre os jogos selecionados para formar uma múltipla real equilibrada
